    case MeasuringReflowRequest::GridInlineLast:
      GridSnapshotProviderTrace(
          aFrame, "grid-before",
          int(aRequest == MeasuringReflowRequest::GridInlineFirst
                  ? BaselineSharingGroup::First : BaselineSharingGroup::Last),
          int(LogicalAxis::Inline), 0, 0, 0, 0);
      baseline.emplace(
          static_cast<nsGridContainerFrame*>(aFrame)->GetIBaseline(
              aRequest == MeasuringReflowRequest::GridInlineFirst
                  ? BaselineSharingGroup::First
                  : BaselineSharingGroup::Last));
      GridSnapshotProviderTrace(
          aFrame, "grid-after",
          int(aRequest == MeasuringReflowRequest::GridInlineFirst
                  ? BaselineSharingGroup::First : BaselineSharingGroup::Last),
          baseline.valueOr(0), int(LogicalAxis::Inline), 0, 0, 0);
      break;
    case MeasuringReflowRequest::Geometry:
      break;
  }
  result.mHasBaseline = baseline.isSome();
  if (baseline) {
    result.mBaselines[LogicalAxis::Block][BaselineSharingGroup::First] =
        *baseline;
  }
  GridSnapshotProviderTrace(aFrame, "capture-end", result.mHasGridBaselines,
                            result.mHasBaseline, int(result.mRequest), 0, 0, 0);
  return result;
}
